class Solution {
public:
    int reverse(int x) {
        int reverse = 0;
        while( x ) {
            if( reverse > INT_MAX/10 || reverse < INT_MIN/10  ) return 0;
            reverse = reverse * 10 + x % 10;
            x /= 10;
        }
        return reverse;
    }
};

class Solution {
public:
    bool armstrongNumber(int n) {
        int n_ = n;
        int a = 0;
        while( n > 0 ){
            int d = n % 10;
            a = a + d * d * d;
            n = n / 10;
        }
        if( n_ ==  a) return true;
        else return false;
    }
};

